contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address target, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(target != address(this));
        require(target != address(c));
        require(address(this).balance >= value);
        require(c.owner() == address(this));

        uint beforeC = address(c).balance;
        uint beforeT = target.balance;

        bool failed;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            failed = true;
        } else {
            failed = false;
        }

        uint afterC = address(c).balance;
        uint afterT = target.balance;

        assert((failed && afterC == beforeC && afterT == beforeT) || (!failed && afterC == beforeC - value && afterT == beforeT + value));
    }
}

